<?php
/**
 * Black-box test suite for index.php.
 *
 * Spins up PHP's built-in web server against throwaway fixture folders
 * (built here, never committed to the repo) and exercises the gallery
 * through real HTTP requests — the same way this project has always been
 * tested by hand (`php -S` + curl). Covers the documented core behaviors
 * plus regression tests for every bug fixed so far.
 *
 * Fixtures:
 *  - "defaults": an unmodified copy of index.php, so TRACK_VIEWS,
 *    ENABLE_THUMBNAIL_CACHE, and AUTO_GROUP_BY_FILENAME are all at their
 *    real off/off/off defaults. Covers the {gallery} marker requirement,
 *    explicit {group:}/{photos:} directives, positional clustering, the
 *    mistake-surfacing notices comment, confirms nothing writes to disk
 *    unless turned on, and that ?download redirects to GitHub rather
 *    than serving the file.
 *  - "optedin": TRACK_VIEWS / ENABLE_THUMBNAIL_CACHE / AUTO_GROUP_BY_FILENAME
 *    all explicitly flipped on. Covers filename auto-grouping, view
 *    tracking (including the per-photo debounce cookie), thumbnail
 *    caching + GC, and directive/security regressions that predate this
 *    file's opt-in-defaults batch.
 *  - "hiddencounts": TRACK_VIEWS on, SHOW_VIEW_COUNTS_PUBLICLY off.
 *    Confirms tracking keeps working server-side while the public badges
 *    never render.
 *  - "mtimesort": PHOTO_SORT_ORDER set to 'mtime'.
 *  - "nonotesbox": every .md rejected, so there's no notes box for the
 *    setup-notices banner to sit in — covers its other placement.
 *
 * Run with: php tests/run.php
 *   The real-ffmpeg checks run only with FFMPEG_TEST_BIN=/path/to/ffmpeg set (or an ffmpeg on the PATH); without one they are
 *   counted as skipped at the end, with the others that need something this PHP or machine lacks.
 * Requires: the GD extension, to synthesize tiny fixture JPEGs.
 * Exits 0 if every check passes, 1 otherwise.
 */

error_reporting(E_ALL);
ini_set('display_errors', '1');
ini_set('memory_limit', '-1');   // (a static CLI build ships with PHP's 128M default, which the archive unit test below outgrows)

if (!extension_loaded('gd')) {
    fwrite(STDERR, "This test suite needs the GD extension to generate fixture images.\n");
    exit(1);
}

$repoRoot = dirname(__DIR__);
$indexSrc = $repoRoot . '/index.php';
$indexContents = file_get_contents($indexSrc);
if (!preg_match("/define\('GALLERY_VERSION', '([^']+)'\)/", $indexContents, $vm)) {
    fwrite(STDERR, "Could not find GALLERY_VERSION in index.php\n");
    exit(1);
}
$currentVersion = $vm[1];

// index.php is built from src/ (php build.php). A stale one would test one thing and ship another: stop here.
if (is_file($repoRoot . '/src/manifest.txt')) {
    $builtCheck = shell_exec(escapeshellarg(PHP_BINARY) . ' ' . escapeshellarg($repoRoot . '/build.php') . ' --check 2>&1');
    $buildOk = str_contains((string) $builtCheck, 'up to date');
    echo ($buildOk ? '  ok    ' : '  FAIL  ') . "index.php is exactly what src/ builds (php build.php --check)\n";
    if (!$buildOk) { echo '        ' . trim((string) $builtCheck) . "\n"; exit(1); }
}

$failCount = 0;
$passCount = 0;
$skipCount = 0;
const PUBLIC_LOG_ID_FOR_TESTS = 'ffffffffff';
$cleanupDirs = [];
$cleanupProcs = [];

register_shutdown_function(function () use (&$cleanupProcs, &$cleanupDirs) {
    foreach ($cleanupProcs as $proc) {
        if (is_resource($proc)) {
            @proc_terminate($proc);
            @proc_close($proc);
        }
    }
    foreach ($cleanupDirs as $dir) {
        rrmdir($dir);
    }
});

/* --------------------------------------------------------------------- */

// A PHP warning or notice in this test script means a check may have run on a missing value (an undefined
// variable is null, and "starts with null" is always true): count it as a failure instead of letting it scroll by.
set_error_handler(function ($errno, $message, $file, $line) {
    if (!(error_reporting() & $errno)) return false;   // @-suppressed on purpose (e.g. polling a server that is still starting)
    global $failCount;
    $failCount++;
    echo "  FAIL  PHP " . ($errno === E_WARNING || $errno === E_USER_WARNING ? 'warning' : 'notice') . " in the test script: $message (line $line)\n";
    return true;
});

function check($description, $condition, $detail = null) {
    global $failCount, $passCount;
    if ($condition) {
        $passCount++;
        echo "  ok    $description\n";
    } else {
        $failCount++;
        echo "  FAIL  $description\n";
        if ($detail !== null) echo '        ' . substr(str_replace("\n", ' ', (string) $detail), 0, 600) . "\n";
    }
}

/** A check that can't be made on this PHP or machine: said out loud, counted separately, never as a pass. */
function skip($description, $why) {
    skip_note("$description  ($why)");   // (skip_note counts it: counting here as well made every skip count twice)
}

/** A skip said as one line (counted like skip()): for the places that print their own words. */
function skip_note($text) {
    global $skipCount;
    $skipCount++;
    echo "  skip  $text\n";
}

function count_occurrences($haystack, $needle, $expected, $label) {
    $actual = substr_count($haystack, $needle);
    check("$label (expected $expected, got $actual)", $actual === $expected);
}

function rrmdir($dir) {
    if (!is_dir($dir)) return;
    foreach (scandir($dir) as $entry) {
        if ($entry === '.' || $entry === '..') continue;
        $path = "$dir/$entry";
        // is_link first: is_dir() is true for a symlink to a directory, and
        // recursing would empty the link's target (possibly outside the
        // fixture) and then fail to rmdir the link itself.
        (is_dir($path) && !is_link($path)) ? rrmdir($path) : @unlink($path);
    }
    @rmdir($dir);
}

function make_jpeg($path, $w, $h, $r, $g, $b) {
    $im = imagecreatetruecolor($w, $h);
    imagefill($im, 0, 0, imagecolorallocate($im, $r, $g, $b));
    imagejpeg($im, $path, 85);
    unset($im);
}

// A minimal but well-formed enough MP4 container to exercise
// video_duration_seconds()'s box-walking: just an ftyp box (ignored,
// skipped over by size) followed by a moov box containing a single mvhd
// (version 0) child with a real duration. No mdat/track data at all —
// not meant to actually play, only to parse.
/* --- "act like a browser" helpers, for the recipe/walkthrough tests ---------
 * The earlier admin tests POST hand-crafted field lists. A real user clicks
 * the page's own forms, which send *every* field with its current value (and
 * carry the stale-edit fingerprint, CSRF token, pre-filled GPS, ...). These
 * parse a rendered page the way a browser would, so a walkthrough can change
 * just what a person would type and submit the rest untouched. */

/** Attributes of a tag's inside as name => decoded value (flags => ''). */
function html_attrs($s) {
    $out = [];
    preg_match_all('#([a-zA-Z_:][-a-zA-Z0-9_:.]*)(?:\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+)))?#', $s, $m, PREG_SET_ORDER);
    foreach ($m as $a) {
        $v = $a[2] ?? ''; if ($v === '' && isset($a[3])) $v = $a[3]; if ($v === '' && isset($a[4])) $v = $a[4];
        $out[strtolower($a[1])] = html_entity_decode($v, ENT_QUOTES, 'UTF-8');
    }
    return $out;
}

/** Every <form method="post"> on a page, as ['attrs' =>, 'html' =>]. */
function html_post_forms($html) {
    preg_match_all('#<form\b([^>]*)>(.*?)</form>#s', $html, $m, PREG_SET_ORDER);
    $forms = [];
    foreach ($m as $f) if (stripos($f[1], 'method="post"') !== false) $forms[] = ['attrs' => $f[1], 'html' => $f[2]];
    return $forms;
}

/** What a browser would submit for a form left untouched: every named,
 *  enabled control with its current value (a checkbox/radio only if
 *  checked, a select's chosen or first option, a textarea's text). */
function form_default_fields($formHtml) {
    $f = [];
    preg_match_all('#<input\b([^>]*)>#i', $formHtml, $ins);
    foreach ($ins[1] as $raw) {
        $a = html_attrs($raw);
        if (!isset($a['name']) || array_key_exists('disabled', $a)) continue;
        $type = strtolower($a['type'] ?? 'text');
        if (in_array($type, ['submit', 'button', 'file', 'image', 'reset'], true)) continue;
        if ($type === 'checkbox' || $type === 'radio') { if (array_key_exists('checked', $a)) $f[$a['name']] = $a['value'] ?? 'on'; continue; }
        $f[$a['name']] = $a['value'] ?? '';
    }
    preg_match_all('#<textarea\b([^>]*)>(.*?)</textarea>#is', $formHtml, $tas, PREG_SET_ORDER);
    foreach ($tas as $ta) { $a = html_attrs($ta[1]); if (isset($a['name']) && !array_key_exists('disabled', $a)) $f[$a['name']] = html_entity_decode($ta[2], ENT_QUOTES, 'UTF-8'); }
    preg_match_all('#<select\b([^>]*)>(.*?)</select>#is', $formHtml, $sels, PREG_SET_ORDER);
    foreach ($sels as $sel) {
        $a = html_attrs($sel[1]); if (!isset($a['name']) || array_key_exists('disabled', $a)) continue;
        preg_match_all('#<option\b([^>]*)>#i', $sel[2], $opts); $chosen = null;
        foreach ($opts[1] as $i => $raw) { $o = html_attrs($raw); if ($chosen === null || array_key_exists('selected', $o)) $chosen = $o['value'] ?? ''; if (array_key_exists('selected', $o)) break; }
        $f[$a['name']] = $chosen ?? '';
    }
    return $f;
}

/** "Click the button" on the first form on $pageHtml containing $needle,
 *  changing only $overrides. $postUrl is the page's own URL (these forms
 *  have no action, so a browser posts them back to it). Returns
 *  [status, body, headers, fieldsSent]. */
function user_submit($postUrl, $pageHtml, $needle, $overrides = [], $headers = [], $carryCookies = false) {
    foreach (html_post_forms($pageHtml) as $form) {
        if (!str_contains($form['html'], $needle)) continue;
        // A photo's privacy and location switches are forms of their own: a search for "the photo's form" means the one with its caption.
        if (str_contains($form['html'], 'value="set_item_flag"') && !str_contains($needle, 'set_item_flag')) continue;
        $fields = array_merge(form_default_fields($form['html']), $overrides);
        if ($carryCookies) {
            // A browser keeps the cookies a response sets and sends them with the redirect that follows: do the same (a form that changes
            // the admin password hands the browser a new sign-in token, and the page it lands on is only shown to that token).
            [$st, $body, $hd] = http_post($postUrl, $fields, $headers, false);
            for ($hop = 0; $hop < 3 && $st >= 300 && $st < 400; $hop++) {
                $loc = ''; foreach ($hd as $h) if (stripos($h, 'Location:') === 0) $loc = trim(substr($h, 9));
                $jar = [];
                foreach ($headers as $i => $h) if (stripos($h, 'Cookie:') === 0) { foreach (explode(';', substr($h, 7)) as $p) { [$n, $v] = array_pad(explode('=', trim($p), 2), 2, ''); if ($n !== '') $jar[$n] = $v; } unset($headers[$i]); }
                foreach ($hd as $h) if (stripos($h, 'Set-Cookie:') === 0) { [$p] = explode(';', trim(substr($h, 11)), 2); [$n, $v] = array_pad(explode('=', $p, 2), 2, ''); if ($v === '' || stripos($h, '1970') !== false) unset($jar[$n]); else $jar[$n] = $v; }
                $headers = array_values($headers); if ($jar) $headers[] = 'Cookie: ' . implode('; ', array_map(fn ($k, $v) => "$k=$v", array_keys($jar), $jar));
                $url = preg_match('#^https?://#', $loc) ? $loc : preg_replace('#[?\#].*$#', '', $postUrl) . (str_starts_with($loc, '?') ? $loc : '?' . ltrim($loc, '/?'));
                [$st, $body, $hd] = http_get($url, $headers, false);
            }
            return [$st, $body, $hd, $fields, $headers];
        }
        [$st, $body, $hd] = http_post($postUrl, $fields, $headers);
        return [$st, $body, $hd, $fields];
    }
    return [0, "NO FORM CONTAINING: $needle", [], []];
}

/** The generated data files start with a PHP guard line (see
 *  data_file_guard_line() in index.php) so a direct request for one
 *  answers 404 with nothing else. These read/write that exact format. */
/** The markup of one of the page's line-drawing icons (see ui_icon in index.php). */
function ico($name) { return '<svg class="ico" aria-hidden="true"><use href="#i-' . $name . '"></use></svg>'; }

/** What the admin page's switches send when a photo's privacy or location switch is flipped (or several photos are chosen). */
function flag_post($url, $page, array $hdrs, $flag, $on, array $names) {
    $csrf = preg_match('/name="csrf_token" value="([^"]+)"/', $page, $m) ? $m[1] : '';
    $fields = ['csrf_token' => $csrf, 'action' => count($names) === 1 ? 'set_item_flag' : 'bulk_item_flag', 'flag' => $flag, 'on' => $on ? '1' : '0'];
    if (count($names) === 1) $fields['file'] = $names[0]; else $fields['files'] = json_encode($names);
    [, $body] = http_post($url, $fields, array_merge($hdrs, ['X-Requested-With: gallery-fetch']));
    return json_decode($body, true) ?? ['ok' => null, 'text' => $body];
}

/** One photo's record as the editor in the viewer asks for it. $root is the gallery's address (ending in /), $file the photo's path. */
function item_get($root, array $hdrs, $file) {
    $j = json_decode(http_get(rtrim($root, '/') . '/?admin&item=' . rawurlencode($file), $hdrs)[1] ?? '', true);
    return is_array($j) ? $j : [];
}

/** A first look at some files, as a visitor's page would make: their thumbnails are asked for, which is when the gallery reads what a file says
 *  about itself (the answer is read from the cache's record afterwards). $names are relative paths. */
function first_look($root, array $names, array $hdrs = []) {
    foreach ($names as $n) http_get(rtrim($root, '/') . '/?img=' . rawurlencode($n) . '&size=thumb', $hdrs);
}

/** Prepare media run to the end, as the admin page's button does (the answers are added up). $extra: e.g. ['again' => '1', 'remake' => '1']. */
function prepare_media_run($root, array $hdrs, array $extra = []) {
    $tok = admin_token($root, $hdrs); $sum = ['worked' => 0, 'read' => 0, 'made' => 0, 'failed' => 0, 'unreadable' => 0, 'total' => 0, 'done' => false, 'ok' => true];
    $from = 0;
    for ($try = 0; $try < 60 && !$sum['done']; $try++) {
        $raw = http_post(rtrim($root, '/') . '/?admin', ['csrf_token' => $tok, 'action' => 'prepare_media', 'from' => (string) $from] + $extra, $hdrs)[1] ?? '';
        $j = json_decode($raw, true) ?: ['ok' => false];
        if (empty($j['ok'])) { $sum['ok'] = false; $sum['raw'] = substr((string) $raw, 0, 200); break; }
        foreach (['worked', 'read', 'made', 'failed', 'unreadable'] as $k) $sum[$k] += (int) ($j[$k] ?? 0);
        $sum['total'] = $j['total']; $sum['done'] = !empty($j['done']); $from = $j['next'];
    }
    return $sum;
}

/** The token the page asks the admin for before it saves anything. */
function admin_token($root, array $hdrs) {
    return json_decode(http_get(rtrim($root, '/') . '/?admin&csrf=1', $hdrs)[1] ?? '', true)['token'] ?? '';
}

/** "Save" for one photo as the editor sends it: what the photo already has (its caption, link and place, a place read from its
 *  GPS too, and the fingerprint) with $overrides on top. $url is the admin address of its folder. Returns like user_submit. */
function item_save($url, array $hdrs, $bare, array $overrides = []) {
    $root = preg_replace('/\?.*$/', '', $url);
    parse_str((string) parse_url($url, PHP_URL_QUERY), $q);
    $j = item_get($root, $hdrs, (($q['folder'] ?? '') !== '' ? $q['folder'] . '/' : '') . $bare);
    $auto = $j['auto'] ?? null;
    $fields = ['csrf_token' => admin_token($root, $hdrs), 'action' => 'save_item', 'file' => $bare, 'caption' => $j['caption'] ?? '', 'web' => $j['web'] ?? '',
        'lat' => ($j['lat'] ?? '') !== '' ? $j['lat'] : ($auto['lat'] ?? ''), 'lng' => ($j['lng'] ?? '') !== '' ? $j['lng'] : ($auto['lng'] ?? ''),
        'loc_label' => $j['label'] ?? '', 'loaded_hash' => $j['hash'] ?? ''];
    $fields = array_merge($fields, $overrides);
    [$st, $body, $hd] = http_post($url, $fields, $hdrs);
    return [$st, $body, $hd, $fields];
}

/** Makes one photo its folder's cover, as the star and the editor's Cover button do. */
function item_cover($url, array $hdrs, $bare) {
    $root = preg_replace('/\?.*$/', '', $url);
    return http_post($url, ['csrf_token' => admin_token($root, $hdrs), 'action' => 'set_cover', 'file' => $bare], $hdrs);
}

/** The markup of the lock or unlock drawing (see ui_icon in index.php). */
function ui_lock_probe($name) { return ico($name); }

function read_data_file($path) {
    $raw = (string) file_get_contents($path);
    if (strncmp($raw, '<?php', 5) === 0) {
        $raw = (string) substr($raw, strpos($raw, "\n") + 1);
    }
    return json_decode($raw, true);
}

/** The settings file (.gallery-config.php): the 404 guard line, then JSON. */
$cfgGuard = "<?php http_response_code(404); exit; ?>\n";
function cfg_text($settings) { return $GLOBALS['cfgGuard'] . json_encode($settings === [] ? new stdClass() : $settings, JSON_HEX_TAG) . "\n"; }
/** The settings file keeps passwords as hashes: does $stored belong to $plain? */
function pw_stored_ok($stored, $plain) { return is_string($stored) && str_starts_with($stored, '$2y$') && password_verify($plain, $stored); }
/** The settings, with a password that is stored as a hash of the given plain one shown as that plain one (so a whole file can be compared). */
function cfg_plain($cfg, $known) { foreach ($known as $name => $plain) if (pw_stored_ok($cfg[$name] ?? null, $plain)) $cfg[$name] = $plain; return $cfg; }
function cfg_read($path) { $raw = (string) file_get_contents($path); $raw = substr($raw, (int) strpos($raw, "\n") + 1); return json_decode($raw, true); }

/** The name the gallery keeps a made file under (see cache_name in index.php): a keyed hash, with the install's secret read from its folder. */
function cache_name_for_tests($root, $file, $variant, $mtime) {
    $secret = preg_match('/^[0-9a-f]{64}$/m', (string) @file_get_contents("$root/.gallery-secret.php"), $m) ? $m[0] : '';
    if (in_array($variant, ['thumb', 'tile', 'tilehd', 'share', 'full', 'cover', 'coverlg'], true)) $variant .= '|icc1';   // (pictures made since the colour profile is kept are named apart from the older, profile-less ones)
    $text = $file . '|' . $variant . '|' . $mtime;
    return $secret === '' ? md5($text) : substr(hash_hmac('sha256', $text, $secret), 0, 32);
}

/** The code in gallery-setup-code.php (what the owner reads in a file manager), or '' when there is no such file. */
function setup_code_for_tests($root) {
    return preg_match('/^Setup code: ([A-Z0-9-]+)$/m', (string) @file_get_contents("$root/gallery-setup-code.php"), $m) ? $m[1] : '';
}

/** A tiny country file in the MaxMind DB format, for the tests: $ranges is ['203.0.113.0/24' => 'US', '2001:db8::/32' => 'DE', ...]; $ver 4 or 6 is the
 *  tree's IP version (an IPv6 tree keeps IPv4 under ::/96), $rec 24, 28 or 32 the bits of each tree record. */
function make_test_mmdb(array $ranges, $ver = 6, $rec = 24) {
    $root = ['c' => [null, null], 'cc' => null]; $ids = [];
    foreach ($ranges as $cidr => $cc) {
        [$addr, $len] = explode('/', $cidr); $bin = inet_pton($addr);
        if (strlen($bin) === 4 && $ver === 6) { $bin = str_repeat("\0", 12) . $bin; $len += 96; }
        $bits = ''; for ($i = 0; $i < $len; $i++) $bits .= (ord($bin[$i >> 3]) >> (7 - ($i & 7))) & 1;
        $n = &$root;
        for ($i = 0; $i < strlen($bits); $i++) { $b = (int) $bits[$i]; if ($n['c'][$b] === null) $n['c'][$b] = ['c' => [null, null], 'cc' => null]; $m = &$n['c'][$b]; unset($n); $n = &$m; unset($m); }
        $n['cc'] = $cc; unset($n);
    }
    $nodes = []; $walk = function (&$n) use (&$walk, &$nodes) { $n['id'] = count($nodes); $nodes[] = &$n; foreach ([0, 1] as $b) if ($n['c'][$b] !== null) $walk($n['c'][$b]); };
    $walk($root);
    $str = fn ($t) => chr(0x40 | strlen($t)) . $t;
    $data = ''; $off = [];
    foreach (array_unique(array_values($ranges)) as $cc) { $off[$cc] = strlen($data); $data .= "\xE1" . $str('country') . "\xE1" . $str('iso_code') . $str($cc); }
    $count = count($nodes);
    $val = function ($c) use ($count, $off) { if ($c === null) return $count; if ($c['c'][0] !== null || $c['c'][1] !== null) return $c['id']; return $c['cc'] === null ? $count : $count + 16 + $off[$c['cc']]; };
    $tree = '';
    foreach ($nodes as $n) {
        $l = $n['c'][0] === null ? ($n['cc'] !== null ? $count + 16 + $off[$n['cc']] : $count) : $n['c'][0]['id'];
        $r = $n['c'][1] === null ? ($n['cc'] !== null ? $count + 16 + $off[$n['cc']] : $count) : $n['c'][1]['id'];
        if ($rec === 24) $tree .= substr(pack('N', $l), 1) . substr(pack('N', $r), 1);
        elseif ($rec === 28) $tree .= substr(pack('N', $l), 1) . chr((($l >> 24) & 0x0F) << 4 | (($r >> 24) & 0x0F)) . substr(pack('N', $r), 1);
        else $tree .= pack('N', $l) . pack('N', $r);
    }
    $u = fn ($type, $v) => ($v === 0 ? chr(($type << 5)) : chr(($type << 5) | strlen(ltrim(pack('N', $v), "\0"))) . ltrim(pack('N', $v), "\0"));
    $meta = "\xE6" . $str('node_count') . $u(6, $count) . $str('record_size') . $u(5, $rec) . $str('ip_version') . $u(5, $ver) . $str('binary_format_major_version') . $u(5, 2) . $str('binary_format_minor_version') . $u(5, 0) . $str('database_type') . $str('Test');
    return $tree . str_repeat("\0", 16) . $data . "\xAB\xCD\xEFMaxMind.com" . $meta;
}

function write_data_file($path, $data) {
    file_put_contents($path, "<?php http_response_code(404); exit; ?>\n" . json_encode($data, JSON_HEX_TAG));
}

/* The visitor log is a SQLite file beside index.php (.gallery-visits.sqlite). These read and write it the way the tests need: vl_log and vl_items give back
 * what the older JSON files held (so a test says what it means: visitors, events, per-item tallies), vl_put adds rows the way the gallery would. */
function vl_path($fx) { foreach (glob("$fx/.gallery-visits-*.sqlite") ?: [] as $f) if (preg_match('~/\.gallery-visits-[0-9a-f]{24}\.sqlite$~', $f)) return $f; return null; }
function vl_exists($fx) { return vl_path($fx) !== null; }
/** The log's database (made, with the gallery's name for it, when the test seeds a log before the gallery has written anything). */
function vl_db($fx) {
    $pdo = new PDO('sqlite:' . (vl_path($fx) ?? $fx . '/.gallery-visits-' . bin2hex(random_bytes(12)) . '.sqlite'));
    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
    $pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);
    $pdo->exec('PRAGMA busy_timeout = 5000');
    return $pdo;
}
function vl_log($fx, $src) {
    $out = ['visitors' => [], 'blocked' => [], 'events' => [], 'via' => [], 'tried' => [], 'folded' => 0];
    if (!vl_exists($fx)) return $out;
    $db = vl_db($fx);
    $q = function ($sql, $p) use ($db) { $st = $db->prepare($sql); $st->execute($p); return $st->fetchAll(); };
    foreach ($q('SELECT * FROM visitors WHERE src = ? ORDER BY first, vid', [$src]) as $r) {
        $v = ['ip' => $r['ip'], 'ua' => $r['ua'], 'country' => $r['country'], 'first' => (int) $r['first'], 'last' => (int) $r['last'], 'opens' => (int) $r['opens'], 'views' => (int) $r['views']];
        if ($r['entry_f'] !== null) $v['entry'] = ['f' => $r['entry_f'], 'h' => $r['entry_h']] + ($r['entry_u'] ? ['u' => 1] : []);
        $out['visitors'][$r['vid']] = $v;
    }
    foreach ($q('SELECT * FROM blocked WHERE src = ?', [$src]) as $r) $out['blocked'][$r['vid']] = ['ip' => $r['ip'], 'ua' => $r['ua'], 'country' => $r['country'], 'first' => (int) $r['first'], 'last' => (int) $r['last'], 'tries' => (int) $r['tries'], 'why' => json_decode($r['why'], true)];
    foreach ($q('SELECT * FROM events WHERE src = ? ORDER BY id', [$src]) as $r) {
        $e = ['t' => (int) $r['t'], 'v' => $r['vid'], 'k' => $r['k']];
        if ((int) $r['t1'] !== (int) $r['t'] || $r['k'] === 'scroll') $e['t1'] = (int) $r['t1'];
        if ($r['f'] !== null) $e['f'] = $r['f'];
        if ($r['d'] !== null) $e['d'] = $r['d'];
        if ((int) $r['n'] > 0) $e['n'] = (int) $r['n'];
        if ($r['s'] !== null) $e['s'] = json_decode($r['s'], true);
        if ($r['k'] === 'arrive') { $e['h'] = $r['h']; if ($r['u']) $e['u'] = 1; }
        $out['events'][] = $e;
    }
    foreach ($q('SELECT * FROM notes WHERE src = ?', [$src]) as $r) { $e = $out[$r['kind']][$r['vid']] ?? ['ip' => $r['ip'], 'n' => [], 'last' => 0]; $e['n'][$r['name']] = (int) $r['n']; $e['last'] = max($e['last'], (int) $r['last']); $out[$r['kind']][$r['vid']] = $e; }
    $m = $q('SELECT v FROM meta WHERE k = ?', ['folded:' . $src]); $out['folded'] = $m ? (int) $m[0]['v'] : 0;
    return $out;
}
function vl_items($fx, $src) {
    $out = ['t' => [], 'f' => []];
    if (!vl_exists($fx)) return $out;
    $db = vl_db($fx);
    $st = $db->prepare('SELECT * FROM items WHERE src = ?'); $st->execute([$src]);
    foreach ($st as $r) {
        $t = [];
        foreach (['sf' => 'sf', 'sl' => 'sl', 'on' => 'opn', 'of' => 'opf', 'ol' => 'opl', 'pn' => 'pln', 'pl' => 'pll', 'dn' => 'dwn', 'dl' => 'dwl'] as $k => $col) if ((int) $r[$col] !== 0) $t[$k] = (int) $r[$col];
        $out['t'][$r['vid'] . '|' . $r['item']] = $t;
    }
    $st = $db->prepare('SELECT * FROM folders WHERE src = ?'); $st->execute([$src]);
    foreach ($st as $r) $out['f'][$r['vid'] . '|' . $r['folder']] = [(int) $r['n'], (int) $r['first'], (int) $r['last']];
    return $out;
}
/** Everything in one table of the log, as rows (for a test that wants to count or look). */
function vl_rows($fx, $table, $where = '1', array $p = []) {
    if (!vl_exists($fx)) return [];
    $st = vl_db($fx)->prepare('SELECT * FROM ' . $table . ' WHERE ' . $where); $st->execute($p);
    return $st->fetchAll();
}
/** Puts one record into the log the way the gallery writes it: a visitor (with its counts) and optionally events. The file is made if it is not there. */
function vl_put($fx, $src, $vid, array $v, array $events = []) {
    $db = vl_db($fx);
    foreach (vl_schema_sql() as $sql) $db->exec($sql);
    $v += ['ip' => '127.0.0.1', 'ua' => 'Safari on Mac', 'country' => '', 'first' => time(), 'last' => time(), 'opens' => 1, 'views' => 0];
    $db->prepare('INSERT OR REPLACE INTO visitors (src, vid, ip, ua, country, first, last, opens, views, entry_f, entry_h, entry_u) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')
       ->execute([$src, $vid, $v['ip'], $v['ua'], $v['country'], $v['first'], $v['last'], $v['opens'], $v['views'], $v['entry_f'] ?? null, $v['entry_h'] ?? null, $v['entry_u'] ?? 0]);
    foreach ($events as $e) {
        $db->prepare('INSERT INTO events (src, t, t1, vid, k, f, d, n, s, h, u) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')
           ->execute([$src, $e['t'], $e['t1'] ?? $e['t'], $vid, $e['k'], $e['f'] ?? null, $e['d'] ?? null, $e['n'] ?? 0, isset($e['s']) ? json_encode($e['s']) : null, $e['h'] ?? null, $e['u'] ?? 0]);
    }
}
function vl_put_event($fx, $src, $vid, array $e) {
    $db = vl_db($fx);
    $db->prepare('INSERT INTO events (src, t, t1, vid, k, f, d, n, s, h, u) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')
       ->execute([$src, $e['t'], $e['t1'] ?? $e['t'], $vid, $e['k'], $e['f'] ?? null, $e['d'] ?? null, $e['n'] ?? 0, isset($e['s']) ? json_encode($e['s']) : null, $e['h'] ?? null, $e['u'] ?? 0]);
}
function vl_put_item($fx, $src, $vid, $item, array $t) {
    $db = vl_db($fx);
    $t += ['sf' => 0, 'sl' => 0, 'opn' => 0, 'opf' => 0, 'opl' => 0, 'pln' => 0, 'pll' => 0, 'dwn' => 0, 'dwl' => 0];
    $db->prepare('INSERT OR REPLACE INTO items (src, vid, item, sf, sl, opn, opf, opl, pln, pll, dwn, dwl) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')
       ->execute([$src, $vid, $item, $t['sf'], $t['sl'], $t['opn'], $t['opf'], $t['opl'], $t['pln'], $t['pll'], $t['dwn'], $t['dwl']]);
}
/** The log's tables, as the gallery makes them (a test that seeds a log before the gallery has written anything). */
function vl_schema_sql() {
    return [
        "CREATE TABLE IF NOT EXISTS visitors (src TEXT NOT NULL, vid TEXT NOT NULL, ip TEXT NOT NULL, ua TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', first INTEGER NOT NULL, last INTEGER NOT NULL, opens INTEGER NOT NULL DEFAULT 0, views INTEGER NOT NULL DEFAULT 0, entry_f TEXT, entry_h TEXT, entry_u INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (src, vid))",
        "CREATE TABLE IF NOT EXISTS blocked (src TEXT NOT NULL, vid TEXT NOT NULL, ip TEXT NOT NULL, ua TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', first INTEGER NOT NULL, last INTEGER NOT NULL, tries INTEGER NOT NULL DEFAULT 0, why TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (src, vid))",
        "CREATE TABLE IF NOT EXISTS notes (src TEXT NOT NULL, kind TEXT NOT NULL, vid TEXT NOT NULL, ip TEXT NOT NULL, name TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, last INTEGER NOT NULL, PRIMARY KEY (src, kind, vid, name))",
        "CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, src TEXT NOT NULL, t INTEGER NOT NULL, t1 INTEGER NOT NULL, vid TEXT NOT NULL, k TEXT NOT NULL, f TEXT, d TEXT, n INTEGER NOT NULL DEFAULT 0, s TEXT, h TEXT, u INTEGER NOT NULL DEFAULT 0)",
        "CREATE TABLE IF NOT EXISTS items (src TEXT NOT NULL, vid TEXT NOT NULL, item TEXT NOT NULL, sf INTEGER NOT NULL DEFAULT 0, sl INTEGER NOT NULL DEFAULT 0, opn INTEGER NOT NULL DEFAULT 0, opf INTEGER NOT NULL DEFAULT 0, opl INTEGER NOT NULL DEFAULT 0, pln INTEGER NOT NULL DEFAULT 0, pll INTEGER NOT NULL DEFAULT 0, dwn INTEGER NOT NULL DEFAULT 0, dwl INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (src, vid, item)) WITHOUT ROWID",
        "CREATE TABLE IF NOT EXISTS folders (src TEXT NOT NULL, vid TEXT NOT NULL, folder TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, first INTEGER NOT NULL, last INTEGER NOT NULL, PRIMARY KEY (src, vid, folder)) WITHOUT ROWID",
        "CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL)",
    ];
}

/** A JPEG whose EXIF block holds only a GPS IFD — PHP has no EXIF writer,
 *  so this hand-assembles a minimal little-endian TIFF inside an APP1
 *  segment. $latDMS/$lngDMS are three [numerator, denominator] pairs. */
/** A JPEG whose EXIF says it was taken at $dateText ("2022:01:01 12:00:00"). */
function make_dated_jpeg($path, $dateText) {
    $im = imagecreatetruecolor(60, 60); imagefill($im, 0, 0, imagecolorallocate($im, 90, 90, 200));
    ob_start(); imagejpeg($im); $jpeg = ob_get_clean(); unset($im);
    $data = $dateText . "\0";
    $exifIfd = 8 + 2 + 12 + 4;
    $dataStart = $exifIfd + 2 + 12 + 4;
    $tiff = 'II' . pack('v', 42) . pack('V', 8)
          . pack('v', 1) . pack('vvVV', 0x8769, 4, 1, $exifIfd) . pack('V', 0)
          . pack('v', 1) . pack('vvVV', 0x9003, 2, strlen($data), $dataStart) . pack('V', 0)
          . $data;
    $exif = "Exif\0\0" . $tiff;
    file_put_contents($path, substr($jpeg, 0, 2) . "\xFF\xE1" . pack('n', strlen($exif) + 2) . $exif . substr($jpeg, 2));
}

/** A JPEG whose EXIF holds the tags given: ['ifd0' => [tag => [type, value]], 'exif' => [...], 'gps' => [...]]. Types: 2 ascii (a string), 3 short (an int), 4 long (an int),
 *  5 rational ([n, d], or a list of pairs), 7 undefined (the raw string). A little-endian TIFF inside an APP1 segment, assembled by hand (PHP has no EXIF writer). */
function make_exif_jpeg($path, $ifds) {
    $im = imagecreatetruecolor(48, 36); imagefill($im, 0, 0, imagecolorallocate($im, 120, 60, 160));
    ob_start(); imagejpeg($im); $jpeg = ob_get_clean(); unset($im);
    $build = function ($entries, $base, &$extra) {
        ksort($entries);
        $n = count($entries); $head = pack('v', $n); $body = ''; $tail = pack('V', 0);
        $dataBase = $base + 2 + 12 * $n + 4; $blob = '';
        foreach ($entries as $tag => [$type, $val]) {
            if ($type === 2) { $raw = $val . "\0"; $count = strlen($raw); }
            elseif ($type === 3) { $raw = pack('v', $val); $count = 1; }
            elseif ($type === 4) { $raw = pack('V', $val); $count = 1; }
            elseif ($type === 5) { $pairs = is_array($val[0]) ? $val : [$val]; $raw = ''; foreach ($pairs as [$nn, $dd]) $raw .= pack('VV', $nn, $dd); $count = count($pairs); }
            else { $raw = $val; $count = strlen($raw); }
            if (strlen($raw) <= 4) { $field = str_pad($raw, 4, "\0"); }
            else { $field = pack('V', $dataBase + strlen($blob)); $blob .= $raw . (strlen($raw) % 2 ? "\0" : ''); }
            $body .= pack('vvV', $tag, $type, $count) . $field;
        }
        $extra = $blob;
        return $head . $body . $tail;
    };
    $ifd0 = $ifds['ifd0'] ?? []; $exif = $ifds['exif'] ?? []; $gps = $ifds['gps'] ?? [];
    $size = function ($entries) { $b = 0; foreach ($entries as [$type, $val]) { $len = $type === 2 ? strlen($val) + 1 : ($type === 3 ? 2 : ($type === 4 ? 4 : ($type === 5 ? 8 * (is_array($val[0]) ? count($val) : 1) : strlen($val)))); if ($len > 4) $b += $len + ($len % 2); } return 2 + 12 * count($entries) + 4 + $b; };
    if ($exif) $ifd0[0x8769] = [4, 0];
    if ($gps) $ifd0[0x8825] = [4, 0];
    $o0 = 8; $oE = $o0 + $size($ifd0); $oG = $oE + ($exif ? $size($exif) : 0);
    if ($exif) $ifd0[0x8769] = [4, $oE];
    if ($gps) $ifd0[0x8825] = [4, $oG];
    $x0 = $xe = $xg = '';
    $t0 = $build($ifd0, $o0, $x0); $te = $exif ? $build($exif, $oE, $xe) : ''; $tg = $gps ? $build($gps, $oG, $xg) : '';
    $seg = "Exif\0\0" . 'II' . pack('v', 42) . pack('V', 8) . $t0 . $x0 . $te . $xe . $tg . $xg;
    file_put_contents($path, substr($jpeg, 0, 2) . "\xFF\xE1" . pack('n', strlen($seg) + 2) . $seg . substr($jpeg, 2));
}

/** The tags a phone's photo carries, all of them: what the info panel may show and what it must never. The sentinels in the text let a test look for them. */
function photo_info_rich_tags() {
    return [
        'ifd0' => [0x010F => [2, 'Apple'], 0x0110 => [2, 'iPhone 15 Pro'], 0x0131 => [2, 'Photos 9.1'], 0x013B => [2, 'SENTINEL-ARTIST Pat'], 0x8298 => [2, 'SENTINEL-COPYRIGHT 2026'], 0x010E => [2, 'SENTINEL-DESCRIPTION']],
        'exif' => [0x9003 => [2, '2026:10:06 14:32:10'], 0x9011 => [2, '+02:00'], 0x829A => [5, [1, 120]], 0x829D => [5, [18, 10]], 0x8827 => [3, 125], 0x920A => [5, [42, 10]], 0x9209 => [3, 16],
                   0xA405 => [3, 26], 0xA434 => [2, 'iPhone 15 Pro back camera 6.86mm f/1.78'], 0xA433 => [2, 'Apple'], 0xA431 => [2, 'SENTINEL-BODYSERIAL'], 0xA435 => [2, 'SENTINEL-LENSSERIAL'],
                   0xA420 => [2, 'SENTINEL-IMAGEID'], 0x9286 => [7, "ASCII\0\0\0" . 'SENTINEL-COMMENT'], 0x927C => [7, 'SENTINEL-MAKERNOTE-BYTES']],
        'gps' => [1 => [2, 'N'], 2 => [5, [[48, 1], [51, 1], [2376, 100]]], 3 => [2, 'E'], 4 => [5, [[2, 1], [21, 1], [846, 100]]]],
    ];
}

/** An MP4 with one video track (H.264, $w x $h, $frames frames over $seconds seconds) and one audio track (AAC, stereo, 48 kHz), and a phone's make and local time. */
function make_mp4_with_tracks($path, $seconds, $w, $h, $frames) {
    $box = function ($type, $body) { return pack('N', 8 + strlen($body)) . $type . $body; };
    $ts = 1000;
    $mvhd = $box('mvhd', pack('N', 0) . pack('N', 3800000000) . pack('N', 0) . pack('N', $ts) . pack('N', $seconds * $ts) . str_repeat("\0", 80));
    $tkhd = fn ($w, $h) => $box('tkhd', pack('N', 3) . str_repeat("\0", 72) . pack('N', $w << 16) . pack('N', $h << 16));
    $mdhd = $box('mdhd', pack('N', 0) . pack('N', 0) . pack('N', 0) . pack('N', $ts) . pack('N', $seconds * $ts) . pack('N', 0));
    $hdlr = fn ($k) => $box('hdlr', pack('N', 0) . pack('N', 0) . $k . str_repeat("\0", 12) . "x\0");
    $vEntry = pack('N', 86) . 'avc1' . str_repeat("\0", 78);
    $aEntry = pack('N', 36) . 'mp4a' . str_repeat("\0", 6) . pack('n', 1) . pack('nn', 0, 0) . pack('N', 0) . pack('n', 2) . pack('n', 16) . pack('N', 0) . pack('N', 48000 << 16);
    $stsd = fn ($entry) => $box('stsd', pack('N', 0) . pack('N', 1) . $entry);
    $stts = $box('stts', pack('N', 0) . pack('N', 1) . pack('N', $frames) . pack('N', 1));
    $trak = fn ($tk, $kind, $entry, $withStts) => $box('trak', $tk . $box('mdia', $mdhd . $hdlr($kind) . $box('minf', $box('stbl', $stsd($entry) . ($withStts ? $stts : '')))));
    $key = fn ($n) => pack('N', 8 + strlen($n)) . 'mdta' . $n;
    $keys = $box('keys', pack('N', 0) . pack('N', 3) . $key('com.apple.quicktime.make') . $key('com.apple.quicktime.model') . $key('com.apple.quicktime.creationdate'));
    $item = fn ($i, $v) => $box(pack('N', $i), $box('data', pack('N', 1) . pack('N', 0) . $v));
    $ilst = $box('ilst', $item(1, 'Apple') . $item(2, 'iPhone 15 Pro') . $item(3, '2026-10-06T14:32:10+0200'));
    $meta = $box('meta', $box('hdlr', pack('N', 0) . pack('N', 0) . 'mdta' . str_repeat("\0", 12) . "\0") . $keys . $ilst);
    $moov = $box('moov', $mvhd . $trak($tkhd($w, $h), 'vide', $vEntry, true) . $trak($tkhd(0, 0), 'soun', $aEntry, false) . $meta);
    file_put_contents($path, $box('ftyp', 'isom' . pack('N', 0)) . $moov);
}

function make_gps_jpeg($path, $latRef, $latDMS, $lngRef, $lngDMS) {
    $im = imagecreatetruecolor(60, 60);
    imagefill($im, 0, 0, imagecolorallocate($im, 10, 200, 10));
    ob_start();
    imagejpeg($im);
    $jpeg = ob_get_clean();
    unset($im);
    $rationals = function ($dms) {
        $out = '';
        foreach ($dms as [$n, $d]) $out .= pack('VV', $n, $d);
        return $out;
    };
    $gpsOffset = 8 + 2 + 12 + 4; // TIFF header + IFD0 (one entry) + next-IFD pointer
    $gpsEntries = 4;
    $dataStart = $gpsOffset + 2 + 12 * $gpsEntries + 4;
    $latData = $rationals($latDMS);
    $lngData = $rationals($lngDMS);
    $tiff = 'II' . pack('v', 42) . pack('V', 8)
          . pack('v', 1) . pack('vvVV', 0x8825, 4, 1, $gpsOffset) . pack('V', 0)
          . pack('v', $gpsEntries)
          . pack('vvV', 1, 2, 2) . $latRef . "\0\0\0"
          . pack('vvVV', 2, 5, 3, $dataStart)
          . pack('vvV', 3, 2, 2) . $lngRef . "\0\0\0"
          . pack('vvVV', 4, 5, 3, $dataStart + strlen($latData))
          . pack('V', 0)
          . $latData . $lngData;
    $exif = "Exif\0\0" . $tiff;
    file_put_contents($path, substr($jpeg, 0, 2) . "\xFF\xE1" . pack('n', strlen($exif) + 2) . $exif . substr($jpeg, 2));
}

/** A JPEG with the EXIF layout an iPhone writes: big-endian ("MM"), IFD0 with
 *  Make/Orientation before the GPS pointer, and a GPS IFD with the extra tags
 *  real phones add (VersionID, altitude, timestamp). Latitude/longitude are
 *  [deg, min, sec*100] integer triples. */
function make_iphone_gps_jpeg($path, $latRef, $lat, $lngRef, $lng) {
    $im = imagecreatetruecolor(40, 40); ob_start(); imagejpeg($im); $j = ob_get_clean(); unset($im);
    $rat = fn($n, $d) => pack('NN', $n, $d);
    $ent = fn($tag, $type, $count, $val) => pack('nnN', $tag, $type, $count) . $val;
    $make = "Apple\0"; $base = 8; $ifd0Len = 2 + 12 * 3 + 4; $gpsEntries = 8; $gpsLen = 2 + 12 * $gpsEntries + 4;
    $gpsOff = $base + $ifd0Len + strlen($make); $dataOff = $gpsOff + $gpsLen;
    $latD = $rat($lat[0], 1) . $rat($lat[1], 1) . $rat($lat[2], 100); $lngD = $rat($lng[0], 1) . $rat($lng[1], 1) . $rat($lng[2], 100);
    $alt = $rat(1234, 100); $ts = $rat(17, 1) . $rat(5, 1) . $rat(33, 1);
    $ifd0 = pack('n', 3) . $ent(0x010F, 2, strlen($make), pack('N', $base + $ifd0Len)) . $ent(0x0112, 3, 1, pack('nn', 6, 0)) . $ent(0x8825, 4, 1, pack('N', $gpsOff)) . pack('N', 0);
    $gps = pack('n', $gpsEntries) . $ent(0, 1, 4, "\x02\x02\x00\x00") . $ent(1, 2, 2, $latRef . "\0\0\0") . $ent(2, 5, 3, pack('N', $dataOff))
         . $ent(3, 2, 2, $lngRef . "\0\0\0") . $ent(4, 5, 3, pack('N', $dataOff + strlen($latD))) . $ent(5, 1, 1, "\x00\0\0\0")
         . $ent(6, 5, 1, pack('N', $dataOff + strlen($latD) + strlen($lngD))) . $ent(7, 5, 3, pack('N', $dataOff + strlen($latD) + strlen($lngD) + strlen($alt))) . pack('N', 0);
    $exif = "Exif\0\0" . 'MM' . pack('n', 42) . pack('N', $base) . $ifd0 . $make . $gps . $latD . $lngD . $alt . $ts;
    file_put_contents($path, substr($j, 0, 2) . "\xFF\xE1" . pack('n', strlen($exif) + 2) . $exif . substr($j, 2));
}

function make_minimal_mp4($path, $durationSeconds, $timescale = 1) {
    $ftypBody = 'isom' . pack('N', 0);
    $ftyp = pack('N', 8 + strlen($ftypBody)) . 'ftyp' . $ftypBody;

    $mvhdBody = pack('N', 0)         // version (0) + flags
              . pack('N', 0)         // creation_time
              . pack('N', 0)         // modification_time
              . pack('N', $timescale)
              . pack('N', (int) round($durationSeconds * $timescale));
    $mvhd = pack('N', 8 + strlen($mvhdBody)) . 'mvhd' . $mvhdBody;

    $moov = pack('N', 8 + strlen($mvhd)) . 'moov' . $mvhd;

    file_put_contents($path, $ftyp . $moov);
}

function find_free_port() {
    global $serverLive;
    for ($try = 0; $try < 50; $try++) {
        $sock = stream_socket_server('tcp://127.0.0.1:0', $errno, $errstr);
        if (!$sock) {
            fwrite(STDERR, "Could not find a free port: $errstr\n");
            exit(1);
        }
        $name = stream_socket_get_name($sock, false);
        fclose($sock);
        $port = (int) substr($name, strrpos($name, ':') + 1);
        if (!isset($serverLive[$port])) return $port;   // (the port of a server the keeper stopped is free but not new: an earlier test may ask for that server again, and would find another gallery's)
    }
    fwrite(STDERR, "Could not find a free port that no earlier server had\n");
    exit(1);
}

/** The test servers, by port: [process, the number of the last request that went to it, the command that started it, whether it is up]. A full run starts hundreds, and each one grows to ~55 MB once it has
 *  served pages: left running they are the biggest thing the run holds in memory (~13 GB of the box's 16), enough to starve the machine. A server holds nothing of its own (its files, sessions and caches are on
 *  disk), so when more than SERVER_KEEP are up the ones used least recently are stopped, and one that is asked for again through http_get / http_post is started again on the same port with the same command. */
const SERVER_KEEP = 30;
$serverLive = [];
$requestTick = 0;
function server_start_cmd($cmd) {
    global $cleanupProcs;
    $proc = proc_open($cmd, [1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']], $pipes);
    if (!is_resource($proc)) { fwrite(STDERR, "Could not start the PHP built-in server\n"); exit(1); }
    $cleanupProcs[] = $proc;
    $port = (int) substr((string) $cmd[4], strrpos((string) $cmd[4], ':') + 1);
    $deadline = microtime(true) + 15;
    while (microtime(true) < $deadline) {
        $conn = @fsockopen('127.0.0.1', $port, $errno, $errstr, 0.2);
        if ($conn) { fclose($conn); return $proc; }
        usleep(100000);
    }
    fwrite(STDERR, "Server on port $port did not start in time\n");
    exit(1);
}
function server_touch($url) {
    global $serverLive, $requestTick;
    $requestTick++;
    if (!preg_match('~^https?://127\.0\.0\.1:(\d+)~', (string) $url, $m) || !isset($serverLive[(int) $m[1]])) return;
    $port = (int) $m[1];
    if (!$serverLive[$port][3]) {   // stopped to save memory: started again, as it was
        $serverLive[$port][0] = server_start_cmd($serverLive[$port][2]);
        $serverLive[$port][3] = true;
    }
    $serverLive[$port][1] = $requestTick;
    server_reap();
}
function server_reap($keep = SERVER_KEEP) {
    global $serverLive;
    $up = array_filter($serverLive, function ($e) { return $e[3]; });
    if (count($up) <= $keep) return;
    uasort($up, function ($a, $b) { return $a[1] <=> $b[1]; });
    foreach ($up as $port => $e) {
        if (count(array_filter($serverLive, function ($x) { return $x[3]; })) <= $keep) break;
        if (is_resource($e[0])) {   // (the process resource stays valid: a test that stops its server itself later finds it already stopped; the wait is so a server asked for again at once does not connect to the one that is still closing)
            @proc_terminate($e[0]);
            for ($w = 0; $w < 40; $w++) { $st = @proc_get_status($e[0]); if (!is_array($st) || !$st['running']) break; usleep(50000); }
        }
        $serverLive[$port][3] = false;
    }
}

function start_server($docroot, $port, $router = null) {
    global $cleanupProcs;
    // argv-array form (no `sh -c` in between) so proc_terminate() in the
    // shutdown handler hits php itself — with a shell wrapper it didn't,
    // and every run orphaned its servers (~35MB each, 10 per run, never
    // reaped). Output goes to /dev/null rather than an undrained pipe,
    // which would eventually fill and block the server on a log write.
    $descriptors = [1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']];
    // A just-copied index.php is inside the first-run setup window (?admin offers to set a password for a few
    // minutes after upload). Fixtures are not "just uploaded", so age the script, as an hour-old install would be.
    if (is_file("$docroot/index.php")) @touch("$docroot/index.php", time() - 3600);
    // opcache is on for the built-in server and re-checks files only every 2 seconds, so a test that swaps index.php
    // and requests it at once could be served the old compiled copy: tests must be deterministic, so it's off here.
    $cmd = [PHP_BINARY, '-d', 'opcache.enable=0', '-S', '127.0.0.1:' . (int) $port, '-t', $docroot];
    if ($router !== null) $cmd[] = $router;   // (a router script, for a test that has to change what the server says it is)
    $proc = proc_open($cmd, $descriptors, $pipes);
    if (!is_resource($proc)) {
        fwrite(STDERR, "Could not start the PHP built-in server\n");
        exit(1);
    }
    $cleanupProcs[] = $proc;

    $deadline = microtime(true) + 15;   // (a long run leaves hundreds of servers up and the machine short of memory: a new one may be slow to start)
    while (microtime(true) < $deadline) {
        $conn = @fsockopen('127.0.0.1', $port, $errno, $errstr, 0.2);
        if ($conn) {
            fclose($conn);
            global $serverLive, $requestTick;
            $serverLive[(int) $port] = [$proc, ++$requestTick, $cmd, true];
            server_reap();
            return $proc;
        }
        usleep(100000);
    }
    fwrite(STDERR, "Server on port $port did not start in time\n");
    exit(1);
}

/** GET request. Returns [statusCode, body, headerLines]. Pass
 *  $followRedirects = false to inspect a redirect response itself
 *  (status + Location header) instead of transparently following it. */
function data_file_guard_line_for_tests() { return "<?php http_response_code(404); exit; ?>\n"; }
function data_file_strip_guard_for_tests($raw) { $raw = (string) $raw; return strncmp($raw, '<?php', 5) === 0 ? substr($raw, strpos($raw, "\n") + 1) : $raw; }
/** The Changes tab as the owner sees it: [the list's answer, its markup with every typed-data entry's lines added (those are fetched when a line is opened)]. */
function changes_full_html($base, $headers) {
    $j = json_decode((string) http_get("$base/?admin&changes_list=1", $headers)[1], true); $html = (string) ($j['html'] ?? '');
    preg_match_all('/class="ch-names ch-lazy" data-id="(\d+)"/', $html, $m);
    foreach ($m[1] as $id) { $e = json_decode((string) http_get("$base/?admin&changes_entry=$id", $headers)[1], true); $html .= (string) ($e['html'] ?? ''); }
    return [$j, $html];
}
function http_get($url, $headers = [], $followRedirects = true) {
    server_touch($url);
    $opts = ['http' => ['method' => 'GET', 'ignore_errors' => true, 'timeout' => 5]];
    if (!$followRedirects) {
        $opts['http']['follow_location'] = 0;
    }
    if ($headers) {
        $opts['http']['header'] = implode("\r\n", $headers);
    }
    $context = stream_context_create($opts);
    $body = @file_get_contents($url, false, $context);
    $status = 0;
    $responseHeaders = $http_response_header ?? [];
    foreach ($responseHeaders as $h) {
        if (preg_match('#^HTTP/\S+\s+(\d+)#', $h, $m)) {
            $status = (int) $m[1];
        }
    }
    return [$status, $body === false ? '' : $body, $responseHeaders];
}

/** POST request with a form-urlencoded body. Returns [statusCode, body,
 *  headerLines], same shape as http_get(). */
function http_post($url, $postData, $headers = [], $followRedirects = true) {
    server_touch($url);
    $opts = ['http' => [
        'method' => 'POST',
        'header' => implode("\r\n", array_merge(['Content-Type: application/x-www-form-urlencoded'], $headers)),
        'content' => http_build_query($postData),
        'ignore_errors' => true,
        'timeout' => 5,
    ]];
    if (!$followRedirects) {
        $opts['http']['follow_location'] = 0;
    }
    $context = stream_context_create($opts);
    $body = @file_get_contents($url, false, $context);
    $status = 0;
    $responseHeaders = $http_response_header ?? [];
    foreach ($responseHeaders as $h) {
        if (preg_match('#^HTTP/\S+\s+(\d+)#', $h, $m)) {
            $status = (int) $m[1];
        }
    }
    return [$status, $body === false ? '' : $body, $responseHeaders];
}

/** Pulls the first Set-Cookie response header's name=value pair (ignoring
 *  path/expiry attributes) out, for resending as a plain Cookie: header
 *  on a follow-up request — enough to carry a PHP session across the
 *  admin tool's CSRF-protected GET-then-POST flow. */
/** Collects every Set-Cookie response header's name=value pair (ignoring
 *  path/expiry attributes) into one semicolon-joined string, suitable for
 *  resending as a single Cookie: header — a response can set more than
 *  one cookie at once (e.g. a PHP session cookie *and* the reveal
 *  cookie, from the same admin login), and a real browser would carry
 *  all of them forward together. Returns null only if there were none. */
function extract_cookie_header($responseHeaders) {
    $pairs = [];
    foreach ($responseHeaders as $h) {
        if (stripos($h, 'Set-Cookie:') === 0) {
            $value = trim(substr($h, strlen('Set-Cookie:')));
            [$pair] = explode(';', $value, 2);
            $pairs[] = $pair;
        }
    }
    return $pairs ? implode('; ', $pairs) : null;
}

/** Pulls the csrf_token hidden input's value out of a rendered admin page. */
function extract_csrf_token($body) {
    return preg_match('/csrf_token" value="([a-f0-9]+)"/', $body, $m) ? $m[1] : null;
}

/** Writes a copy of index.php with one or more constants patched. */
function write_patched_index($destPath, $indexContents, $patches) {
    $content = $indexContents;
    foreach ($patches as $const => $value) {
        if ($const === 'ENABLE_MAP') continue;   // (the gallery-wide Map switch is gone: the map follows ENABLE_PHOTO_LOCATION, which the same fixtures patch)
        // A setting is define('NAME', gallery_setting('NAME', default[, allowed])): replace the whole define.
        $pattern = "/define\('" . preg_quote($const, '/') . "',\s*gallery_setting\([^)]*\)\)/";
        $replacement = "define('$const', " . $value . ')';
        $new = preg_replace($pattern, $replacement, $content, 1, $count);
        if ($count !== 1) {
            fwrite(STDERR, "Could not patch constant $const in index.php copy\n");
            exit(1);
        }
        $content = $new;
    }
    file_put_contents($destPath, $content);
}

/** index.php's link_state(), for the test script (which never loads index.php): the same rules. */
function link_state_for_tests($l, $now = null) {
    $now = $now ?? time();
    if (($l['status'] ?? '') === 'revoked') return 'revoked';
    if (($l['status'] ?? '') === 'paused') return 'paused';
    if ((int) ($l['endsAt'] ?? 0) > 0 && $now >= (int) $l['endsAt']) return 'expired';
    if ((int) ($l['startsAt'] ?? 0) > $now) return 'scheduled';
    if ((int) ($l['maxOpens'] ?? 0) > 0 && (int) ($l['opens'] ?? 0) >= (int) $l['maxOpens']) return 'used_up';
    return 'active';
}

/** The visitors in a link's log file, for the test script. */
function link_log_visitors_for_tests($file) {
    $raw = (string) @file_get_contents($file);
    $d = json_decode(strncmp($raw, '<?php', 5) === 0 ? substr($raw, strpos($raw, "\n") + 1) : $raw, true);
    return is_array($d) ? ($d['visitors'] ?? []) : [];
}

/** The regular files in a folder, dot files too (glob() with GLOB_BRACE does this, but a static or musl PHP build has no GLOB_BRACE). */
function dir_files($dir) { $out = []; foreach ((array) @scandir($dir) as $n) if ($n !== '.' && $n !== '..' && is_file("$dir/$n")) $out[] = "$dir/$n"; return $out; }
function new_fixture_dir($label) {
    global $cleanupDirs;
    $dir = sys_get_temp_dir() . '/gallery-tests-' . $label . '-' . bin2hex(random_bytes(4));
    mkdir($dir, 0775, true);
    $cleanupDirs[] = $dir;
    return $dir;
}

